<script setup lang="ts">
import type { PopupPlacement } from './internal/floating';
import { computed, ref } from 'vue'; import Select from './Select.vue';
import './styles/cascader.css';
interface Option { label: string; value: string; disabled?: boolean; children?: Option[]; isLeaf?: boolean }
const props = withDefaults(defineProps<{ options: Option[]; modelValue?: string[]; defaultValue?: string[]; placeholder?: string; expandTrigger?: 'click' | 'hover'; changeOnSelect?: boolean; showSearch?: boolean; notFoundContent?: string; disabled?: boolean; allowClear?: boolean; size?: 'sm' | 'md' | 'lg'; label?: string; hint?: string; error?: string; status?: 'error' | 'warning'; placement?: PopupPlacement; popupClassName?: string; popupStyle?: import('vue').CSSProperties; popupMatchSelectWidth?: boolean; open?: boolean }>(), { open: undefined, placeholder: '请选择…', expandTrigger: 'click', notFoundContent: '暂无匹配选项', allowClear: true, size: 'md' });
const emit = defineEmits<{ 'update:modelValue': [path: string[]]; change: [path: string[], options: Option[]]; 'update:open': [value: boolean] }>();
const inner = ref(props.defaultValue ?? []), path = ref(props.modelValue ?? props.defaultValue ?? []), innerOpen = ref(false), query = ref(''); const value = computed(() => props.modelValue ?? inner.value);
function resolve(keys: string[]) { const result: Option[] = []; let level = props.options; for (const key of keys) { const item = level.find(item => item.value === key); if (!item) break; result.push(item); level = item.children ?? []; } return result; }
const levels = computed(() => { const result: Option[][] = [props.options]; let level = props.options; for (const key of path.value) { const item = level.find(item => item.value === key); if (!item?.children?.length) break; result.push(item.children); level = item.children; } return result; });
function collect(nodes: Option[], trail: Option[] = []): Option[][] { return nodes.flatMap(node => { const path = [...trail, node]; return [...(!node.children?.length || props.changeOnSelect ? [path] : []), ...collect(node.children ?? [], path)]; }); }
const paths = computed(() => collect(props.options)); const choices = computed(() => paths.value.map(path => ({ label: path.map(item => item.label).join(' / '), value: JSON.stringify(path.map(item => item.value)), disabled: path.some(item => item.disabled) })));
const selectedValue = computed(() => value.value.length ? JSON.stringify(value.value) : '');
function setOpen(next: boolean) { if (props.open === undefined) innerOpen.value = next; if (next) path.value = [...value.value]; else query.value = ''; emit('update:open', next); }
function update(next: string[]) { if (props.modelValue === undefined) inner.value = next; emit('update:modelValue', next); emit('change', next, resolve(next)); }
function choose(item: Option, index: number, hover = false) { if (item.disabled) return; path.value = [...path.value.slice(0, index), item.value]; if (!hover && (props.changeOnSelect || !item.children?.length || item.isLeaf)) { update(path.value); if (!item.children?.length || item.isLeaf) setOpen(false); } }
function select(next: string | string[]) { if (typeof next === 'string') update(next ? JSON.parse(next) : []); }
</script>
<template><Select :status="status" :placement="placement" :popup-class-name="popupClassName" :popup-style="popupStyle" :popup-match-select-width="popupMatchSelectWidth" :searchable="showSearch" @search="query = $event" :options="choices" :model-value="selectedValue" :placeholder="placeholder" :disabled="disabled" :allow-clear="allowClear" :size="size" :label="label" :hint="hint" :error="error" :open="open ?? innerOpen" @update:open="setOpen" @update:model-value="select"><template #label><slot name="display" :labels="resolve(value).map(item => item.label)" :selected-options="resolve(value)">{{ resolve(value).map(item => item.label).join(' / ') }}</slot></template><template #popup><div class="at-cascader__popup"><ul v-if="query" class="at-cascader__search-list" role="listbox"><li v-for="choice in choices.filter(item => item.label.toLocaleLowerCase().includes(query.toLocaleLowerCase()))" :key="choice.value" role="option" :aria-selected="choice.value === selectedValue" :aria-disabled="choice.disabled" class="at-option" @click="!choice.disabled && (select(choice.value), setOpen(false))">{{ choice.label }}</li></ul><div v-else class="at-cascader__columns"><ul v-for="(options, index) in levels" :key="index" class="at-cascader__column" role="listbox" :aria-label="`第 ${index + 1} 级`"><li v-for="item in options" :key="item.value" role="option" :aria-selected="path[index] === item.value" :aria-disabled="item.disabled" :class="['at-cascader__option', 'at-option', { 'at-option--selected': path[index] === item.value, 'at-option--disabled': item.disabled }]" :tabindex="item.disabled ? -1 : 0" @click="choose(item, index)" @keydown.enter.prevent="choose(item, index)" @mouseenter="expandTrigger === 'hover' && item.children?.length && choose(item, index, true)"><slot name="option" :option="item">{{ item.label }}<span v-if="item.children?.length" aria-hidden="true">›</span></slot></li></ul></div></div></template></Select></template>
